use super::*;
use semio_framework_os_kernel::{ArtifactSqliteSnapshot,sqlite_snapshot::*};
fn fixture()->Grid2dSnapshot{let f:serde_json::Value=serde_json::from_str(include_str!("../../🧫️fixtures/🪶️sqlite/🔣️.json")).unwrap();let text=|v:&serde_json::Value|v.as_str().unwrap().to_string();let word=|v:&serde_json::Value|f64::from_bits(u64::from_str_radix(v.as_str().unwrap(),16).unwrap());let color=|v:&serde_json::Value|WfcColor{r:v["r"].as_u64().unwrap() as u32,g:v["g"].as_u64().unwrap() as u32,b:v["b"].as_u64().unwrap() as u32,a:v["a"].as_u64().unwrap() as u32};let point=|v:&serde_json::Value|WfcPoint2{x:word(&v[0]),y:word(&v[1])};Grid2dSnapshot{schema:text(&f["schema"]),seed:f["seed"].as_str().unwrap().parse().unwrap(),width:u32::MAX,height:2,cell_width:word(&f["cellWidthBits"]),cell_height:word(&f["cellHeightBits"]),periodic_x:true,periodic_y:false,tiles:f["tiles"].as_array().unwrap().iter().map(|t|{let m=&t["media"];let media=match m["kind"].as_str().unwrap(){"bitmap"=>WfcTileMedia2d::Bitmap{width:m["width"].as_u64().unwrap() as u32,height:m["height"].as_u64().unwrap() as u32,palette:m["palette"].as_array().unwrap().iter().map(color).collect(),pixels:text(&m["pixels"])},"vector"=>WfcTileMedia2d::Vector{paths:m["paths"].as_array().unwrap().iter().map(|p|WfcVectorPath{stroke_width:word(&p["strokeWidthBits"]),fill:p.get("fill").map(color),stroke:p.get("stroke").map(color),segments:p["segments"].as_array().unwrap().iter().map(|s|match s["kind"].as_str().unwrap(){"moveTo"=>WfcPathSegment::MoveTo{to:point(&s["toBits"])},"lineTo"=>WfcPathSegment::LineTo{to:point(&s["toBits"])},"quadTo"=>WfcPathSegment::QuadTo{ctrl:point(&s["ctrlBits"]),to:point(&s["toBits"])},"cubicTo"=>WfcPathSegment::CubicTo{ctrl1:point(&s["ctrl1Bits"]),ctrl2:point(&s["ctrl2Bits"]),to:point(&s["toBits"])},"close"=>WfcPathSegment::Close,_=>panic!("segment")}).collect()}).collect()},"image"=>{let v=&m["target"];WfcTileMedia2d::Image{child:store::ArtifactChild::new(text(&m["childId"]),store::os_io::ArtifactRef{artifact_id:text(&v["artifactId"]),dialect:store::os_io::ArtifactDialect{artifact_kind:text(&v["dialect"]["artifactKind"]),standard:text(&v["dialect"]["standard"]),subset:text(&v["dialect"]["subset"])}})}},_=>panic!("media")};WfcTile2d{id:text(&t["id"]),label:t.get("label").map(text),weight:word(&t["weightBits"]),media}}).collect(),rules:vec![WfcAdjacencyRule2d{id:"adjacency".into(),tile_a_id:"bitmap".into(),tile_b_id:"vector 🧬".into(),direction:WfcDirection2d::Bottom,allowed:false}],pinned:vec![WfcPinnedCell2d{x:u32::MAX,y:1,tile_id:"image".into()}],masked:vec![WfcCell2d{x:4,y:5},WfcCell2d{x:0,y:0}]}}
fn project(s:&Grid2dSnapshot)->SqliteDatabase{s.to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap()}
fn restore(d:&SqliteDatabase)->Result<Grid2dSnapshot,String>{Grid2dSnapshot::from_sqlite_database(d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default()))}
#[test]fn sqlite_snapshot_wfc_grid2d_all_media_path_and_words(){let s=fixture();let d=project(&s);let bytes=export_sqlite_database(&d,SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let actual=restore(&import_sqlite_database(&bytes,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();assert_eq!(project(&actual),d);assert_eq!(actual.seed,u64::MAX);assert_eq!(actual.cell_height.to_bits(),0x7ff0000000000001);assert_eq!(store::ArtifactPack::encode_pack(&actual),store::ArtifactPack::encode_pack(&s));assert_eq!(store::ArtifactDsl::print_dsl(&actual),store::ArtifactDsl::print_dsl(&s));assert_eq!(restore(&project(&Grid2dSnapshot::default())).unwrap(),Grid2dSnapshot::default());}
#[test]fn sqlite_snapshot_wfc_grid2d_independent_queries_and_edit(){use std::io::Write;use std::process::{Command,Stdio};let bytes=export_sqlite_database(&project(&fixture()),SqliteDatabaseLimits::default(),&mut |_|true).unwrap();let script="import{Database}from'bun:sqlite';const d=Database.deserialize(new Uint8Array(await Bun.stdin.arrayBuffer()));if(d.query('PRAGMA integrity_check').get().integrity_check!=='ok'||d.query('PRAGMA foreign_key_check').all().length)throw Error('integrity');const r=d.query('SELECT a.authored_id AS a,b.authored_id AS b,direction FROM wfc_grid2d_rule JOIN wfc_grid2d_tile a ON tile_a_id=a.id JOIN wfc_grid2d_tile b ON tile_b_id=b.id').get();if(r.a!=='bitmap'||r.b!=='vector 🧬'||r.direction!=='BOTTOM')throw Error('rule FK');if(d.query('SELECT kind FROM wfc_grid2d_segment ORDER BY ordinal').all().map(r=>r.kind).join(',')!=='moveTo,lineTo,quadTo,cubicTo,close')throw Error('commands');d.query(\"UPDATE wfc_grid2d_path_color SET red=7 WHERE role='stroke'\").run();await Bun.write(Bun.stdout,d.serialize());";let mut c=Command::new("bun").args(["-e",script]).stdin(Stdio::piped()).stdout(Stdio::piped()).stderr(Stdio::piped()).spawn().unwrap();c.stdin.take().unwrap().write_all(&bytes).unwrap();let o=c.wait_with_output().unwrap();assert!(o.status.success(),"{}",String::from_utf8_lossy(&o.stderr));let actual=restore(&import_sqlite_database(&o.stdout,SqliteDatabaseLimits::default(),&mut |_|true).unwrap()).unwrap();if let WfcTileMedia2d::Vector{paths}=&actual.tiles[1].media{assert_eq!(paths[0].stroke.unwrap().r,7)}else{panic!("media")}}
#[test]fn sqlite_snapshot_wfc_grid2d_invalid_typed_graph_and_controls(){let d=project(&fixture());for n in 0..7{let mut m=d.clone();match n{0=>m.table_mut("wfc_grid2d_rule").unwrap().rows[0].values[4]=SqliteValue::Integer(999),1=>m.table_mut("wfc_grid2d_segment").unwrap().rows[0].values[2]=SqliteValue::Integer(99),2=>m.table_mut("wfc_grid2d_path_color").unwrap().rows[0].values[2]=SqliteValue::Text("unknown".into()),3=>m.table_mut("wfc_grid2d_palette").unwrap().rows[0].values[3]=SqliteValue::Integer(-1),4=>m.table_mut("wfc_grid2d_segment").unwrap().rows[4].values[4]=SqliteValue::Real(1.),5=>m.table_mut("wfc_grid2d_image").unwrap().rows.clear(),_=>m.table_mut("wfc_grid2d_document").unwrap().rows[0].values[9]=SqliteValue::Integer(1)};assert!(restore(&m).is_err(),"case {n}");}assert!(fixture().to_sqlite_database(&mut SqliteSnapshotControl::new(&mut |_|false,SqliteDatabaseLimits::default())).is_err());assert!(Grid2dSnapshot::from_sqlite_database(&d,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_value_bytes:4,..SqliteDatabaseLimits::default()})).is_err());}
#[test]fn sqlite_snapshot_wfc_grid2d_actual_native_declaration(){let s=fixture();let codec=crate::standards::v1::subsets::any::io::io().native.codec;let provider=codec.snapshot_sqlite.unwrap();let dialect=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.grid2d".into(),standard:"1".into(),subset:"*".into()};for encoding in [SnapshotEncoding::Binary,SnapshotEncoding::Text]{let actual=(provider.import)("grid2d",&dialect,project(&s),encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).unwrap().value;let expected=match encoding{SnapshotEncoding::Binary=>store::os_io::IoPayload::Binary(store::ArtifactPack::encode_pack(&s)),SnapshotEncoding::Text=>store::os_io::IoPayload::Text(store::ArtifactDsl::print_dsl(&s))};assert_eq!(actual,expected);assert!(s.preflight_sqlite_snapshot_encoding(encoding,&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits{max_file_bytes:16,..SqliteDatabaseLimits::default()})).is_err());}let wrong=store::os_io::ArtifactDialect{artifact_kind:"s.wfc.grid2d".into(),standard:"1".into(),subset:"named".into()};assert!(s.validate_sqlite_snapshot_subset(&wrong,&project(&s),&mut SqliteSnapshotControl::new(&mut |_|true,SqliteDatabaseLimits::default())).is_err());}
